if (vars.groupPostSkippedByKnownApproval === true || vars.skipGroupPostByKnownApproval === true) {
  const isPending = vars.groupPostRequiresPostApproval === true;
  vars.groupPostIsPending = isPending;
  return {
    isPending,
    postUrl: '',
    skippedPost: true,
    source: vars.groupPostApprovalSource || 'account_contact',
    pendingCheckConclusive: true
  };
}

const groupPostUrl = String(vars.groupPostPostUrl || input.postUrl || input.link || '').trim();
if (groupPostUrl.includes('/pending_posts/')) {
  vars.groupPostIsPending = true;
  return {
    isPending: true,
    postUrl: groupPostUrl,
    pendingCheckConclusive: true,
    source: 'post_url'
  };
}

function extractGroupKey(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';

  const cleaned = raw.replace(/^\/+|\/+$/g, '');
  if (/^groups\//i.test(cleaned)) {
    const parts = cleaned.split('/').filter(Boolean);
    return parts[1] || '';
  }

  try {
    const url = new URL(/^https?:\/\//i.test(raw) ? raw : 'https://' + raw);
    const parts = url.pathname.split('/').filter(Boolean);
    const groupIdx = parts.findIndex(part => part.toLowerCase() === 'groups');
    if (groupIdx >= 0 && parts[groupIdx + 1]) return parts[groupIdx + 1];
  } catch {}

  if (/^[a-zA-Z0-9._-]+$/.test(cleaned)) return cleaned;
  return '';
}

function buildPendingContentUrl() {
  const sources = [
    vars.targetUrl,
    vars.inputDataUid,
    input.targetUrl,
    groupPostUrl,
    vars.groupPostRawPostLink,
    input.rawPostLink
  ];

  for (const source of sources) {
    const groupKey = extractGroupKey(source);
    if (groupKey) {
      return 'https://www.facebook.com/groups/' + encodeURIComponent(groupKey) + '/my_pending_content';
    }
  }
  return '';
}

const pendingContentUrl = buildPendingContentUrl();
if (!pendingContentUrl) {
  vars.groupPostIsPending = false;
  helpers.log('Không dựng được URL my_pending_content để kiểm tra bài chờ duyệt');
  return {
    isPending: false,
    postUrl: groupPostUrl,
    pendingContentUrl: '',
    pendingContentLinks: [],
    pendingCheckConclusive: false,
    source: 'missing_pending_content_url'
  };
}

const rawSelector = await helpers.element('GroupPostRawPostLink');
const linkSelector = await helpers.element('GroupPostPostLink');

helpers.log('Đang kiểm tra trang bài chờ duyệt: ' + pendingContentUrl);

let check;
try {
  check = await helpers.checkGroupPendingContent({
    url: pendingContentUrl,
    rawSelector,
    linkSelector,
    timeoutMs: 18000
  });
} catch (err) {
  const message = err && err.message ? String(err.message) : String(err);
  vars.groupPostIsPending = false;
  helpers.log('Không kiểm tra được trang bài chờ duyệt: ' + message);
  return {
    isPending: false,
    postUrl: groupPostUrl,
    pendingContentUrl,
    pendingContentLinks: [],
    pendingCheckConclusive: false,
    source: 'pending_content_error',
    error: message
  };
}

const links = Array.isArray(check && check.links)
  ? check.links.map(link => String(link || '').trim()).filter(Boolean)
  : [];
const conclusive = check && check.conclusive === true;

if (!conclusive) {
  const message = check && check.error ? String(check.error) : 'không kết luận được';
  vars.groupPostIsPending = false;
  helpers.log('Không kết luận được trạng thái chờ duyệt từ my_pending_content: ' + message);
  return {
    isPending: false,
    postUrl: groupPostUrl,
    pendingContentUrl,
    pendingContentLinks: links,
    pendingCheckConclusive: false,
    source: 'pending_content_inconclusive',
    error: message
  };
}

const isPending = links.length > 0;
vars.groupPostIsPending = isPending;

helpers.log(isPending
  ? 'Phát hiện bài trong trang chờ duyệt của group'
  : 'Không thấy bài trong trang chờ duyệt của group');

return {
  isPending,
  postUrl: groupPostUrl,
  pendingContentUrl,
  pendingContentLinks: links,
  pendingCheckConclusive: true,
  source: isPending ? 'pending_content' : 'pending_content_empty'
};

const submitButton = await helpers.element('GroupPostSubmitButtonAfterClick');
const frequencyLimitError = await helpers.element('GroupPostFrequencyLimitError');
const publishMedia = Array.isArray(vars.images) ? vars.images : []
const publishHasVideo = publishMedia.some(path => /^data:video\//i.test(String(path || '')) || /\.(3g2|3gp|avi|m2ts|m4v|mkv|mov|mp4|mpeg|mpg|ogv|webm|wmv)(?:[?#].*)?$/i.test(String(path || '')))
const publishTimeoutMs = publishHasVideo ? 180000 : 60000
const publishStarted = Number(vars.facebookPostPublishStartedAt) || Date.now();
let posted = false;
let message = '';

async function hasVisibleElement(selector) {
  return await page.evaluate(`
    const selector = __args[0];

    function isVisible(el) {
      if (!el) return false;
      const style = window.getComputedStyle(el);
      if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return false;
      const rect = el.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
    }

    function xpathAll(xpath) {
      const out = [];
      if (!xpath) return out;
      try {
        const result = document.evaluate(xpath, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
        for (let i = 0; i < result.snapshotLength; i++) {
          const item = result.snapshotItem(i);
          if (item) out.push(item);
        }
      } catch {}
      return out;
    }

    return xpathAll(selector).some(isVisible);
  `, selector);
}

while (true) {
  if (signal.aborted) throw new Error('Đã dừng chờ xác nhận đăng bài');
  if (!await hasVisibleElement(submitButton)) {
    posted = true;
    message = 'Form đăng bài đã đóng';
    break;
  }
  const remainingMs = publishTimeoutMs - (Date.now() - publishStarted);
  if (remainingMs <= 0) break;
  await helpers.sleep(Math.min(500, remainingMs), signal);
}
if (!posted) {
  const hasFrequencyLimitError = await hasVisibleElement(frequencyLimitError);
  if (hasFrequencyLimitError) {
    message = 'Facebook báo giới hạn tần suất bạn đăng bài';
    vars.groupPostSubmitted = false;
    vars.groupPostFrequencyLimitError = true;
    helpers.log(message);
    throw new Error(message);
  }
  message = 'Form đăng bài chưa đóng sau ' + (publishTimeoutMs / 1000) + ' giây';
}

vars.groupPostSubmitted = posted;
if (!posted) helpers.log(message);

return {
  ok: posted,
  posted,
  submitClosed: posted,
  publishTimeoutMs,
  message
};

const rawSelector = await helpers.element('GroupPostRawPostLink');
const linkSelector = await helpers.element('GroupPostPostLink');

const result = await page.evaluate(`
  const rawSelector = __args[0];
  const linkSelector = __args[1];

  function delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  function xpathAll(xpath) {
    const out = [];
    if (!xpath) return out;
    try {
      const result = document.evaluate(xpath, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
      for (let i = 0; i < result.snapshotLength; i++) {
        const item = result.snapshotItem(i);
        if (item) out.push(item);
      }
    } catch {}
    return out;
  }

  function hrefOf(el) {
    return el ? (el.href || el.getAttribute('href') || '') : '';
  }

  function cleanPostHref(href) {
    if (!href) return '';
    try {
      const url = new URL(href, location.href);
      if (/^(m|mbasic|mobile)\\.facebook\\.com$/i.test(url.hostname)) {
        url.hostname = 'www.facebook.com';
      }
      url.hash = '';
      Array.from(url.searchParams.keys()).forEach(key => {
        if (
          key.startsWith('__') ||
          key === 'mibextid' ||
          key === 'ref' ||
          key === 'locale' ||
          key === 'comment_id' ||
          key === 'reply_comment_id'
        ) {
          url.searchParams.delete(key);
        }
      });
      return url.href;
    } catch {
      return String(href || '').trim();
    }
  }

  function isCommentPermalink(href) {
    if (!href) return false;
    try {
      const url = new URL(href, location.href);
      if (url.searchParams.has('comment_id') || url.searchParams.has('reply_comment_id')) return true;
      const rawQuery = String(url.search || '').toLowerCase();
      return rawQuery.includes('comment_id=') || rawQuery.includes('reply_comment_id=');
    } catch {
      const raw = String(href || '').toLowerCase();
      return raw.includes('comment_id=') || raw.includes('reply_comment_id=');
    }
  }

  function isPostPermalink(href) {
    if (!href || isCommentPermalink(href)) return false;
    return href.includes('/pending_posts/') || href.includes('/posts/') || href.includes('story_fbid=');
  }

  function simulateFocusin(element) {
    if (!element) return;
    try {
      element.scrollIntoView({ block: 'center', inline: 'nearest' });
    } catch {}
    try {
      element.dispatchEvent(new FocusEvent('focusin', {
        view: window,
        bubbles: true,
        cancelable: true
      }));
    } catch {
      try { element.dispatchEvent(new Event('focusin', { bubbles: true, cancelable: true })); } catch {}
    }
  }

  const rawEl = xpathAll(rawSelector)[0] || null;
  const rawPostLink = rawEl ? cleanPostHref(hrefOf(rawEl)) : '';
  if (rawEl) {
    simulateFocusin(rawEl);
    await delay(700);
  }

  const postUrl = xpathAll(linkSelector)
    .map(el => cleanPostHref(hrefOf(el)))
    .filter(Boolean)
    .filter(isPostPermalink)[0] || '';

  return { rawPostLink, postUrl };
`, rawSelector, linkSelector);

const rawPostLink = String(result && result.rawPostLink ? result.rawPostLink : '').trim();
const postUrl = String(result && result.postUrl ? result.postUrl : '').trim();
vars.groupPostRawPostLink = rawPostLink;
vars.groupPostPostUrl = postUrl;
helpers.log(postUrl ? 'Đã lấy được link bài post' : 'Chưa lấy được link bài post sau khi đăng');

return {
  ok: postUrl.length > 0,
  rawPostLink,
  postUrl,
  link: postUrl
};
